def export_torchscript():
    net = Model()
    net.float()
    net.eval()

    torch.manual_seed(0)
    v_0 = torch.rand(1, 3, 1536, 1536, dtype=torch.float)

    mod = torch.jit.trace(net, v_0)
    mod.save("dptpro_pnnx.py.pt")

def export_onnx():
    net = Model()
    net.float()
    net.eval()

    torch.manual_seed(0)
    v_0 = torch.rand(1, 3, 1536, 1536, dtype=torch.float)

    torch.onnx.export(net, v_0, "dptpro_pnnx.py.onnx", export_params=True, operator_export_type=torch.onnx.OperatorExportTypes.ONNX_ATEN_FALLBACK, opset_version=13, input_names=['in0'], output_names=['out0'])

@torch.no_grad()
def test_inference():
    net = Model()
    net.float()
    net.eval()

    # Load image.
    filename = "data/test_input_image2.jpg"
    raw_image = cv2.imread(filename)
    # Possible OK when use RGB.
    image = cv2.cvtColor(raw_image, cv2.COLOR_BGR2RGB)
    transform = Compose(
        [
            ToTensor(),
            Lambda(lambda x: x.to('cpu')),
            Normalize([0.5, 0.5, 0.5], [0.5, 0.5, 0.5]),
            ConvertImageDtype(torch.half),
        ]
    )
    image = transform(image)
    if len(image.shape) == 3:
        image = image.unsqueeze(0)
    # _, _, _, width = image.shape


    return net(image)

if __name__ == "__main__":
    # export_onnx()
    print(test_inference())
